"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useMemo, useRef } from "react";
import * as THREE from "three";
import {
  CAMERA_FOV_CURVE,
  CAMERA_THROUGH_FOV,
  CAMERA_THROUGH_Z,
  CAMERA_X_CURVE,
  CAMERA_Y_CURVE,
  CAMERA_Z_CURVE,
  TRUCK_Z_CURVE,
  type TruckSceneState,
} from "@/lib/loader/sceneState";
import { sampleCurve } from "@/lib/loader/truckArt";

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/**
 * Camera rig.
 *
 * Reads `TruckSceneState` every frame rather than being tweened directly, so
 * GSAP owns the pacing while the geometry of the shot lives here. Handheld
 * shake is applied as rotation *after* `lookAt`, otherwise `lookAt` would
 * cancel it out.
 */
export function TruckCamera({
  state,
  reduced,
}: {
  state: TruckSceneState;
  reduced: boolean;
}) {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  const target = useMemo(() => new THREE.Vector3(), []);
  const forward = useMemo(() => new THREE.Vector3(0, 1.45, -40), []);
  const lastFov = useRef(-1);

  useFrame(() => {
    if (!state.running) return;

    const { p, through, shake } = state;

    const x = sampleCurve(CAMERA_X_CURVE, p);
    const y = sampleCurve(CAMERA_Y_CURVE, p);
    const z = lerp(sampleCurve(CAMERA_Z_CURVE, p), CAMERA_THROUGH_Z, through);
    const fov = lerp(sampleCurve(CAMERA_FOV_CURVE, p), CAMERA_THROUGH_FOV, through);

    const t = performance.now() * 0.001;
    // Two incommensurate frequencies read as handheld rather than as a sine wave.
    const jitter = reduced ? 0 : shake;
    const jx = (Math.sin(t * 23.7) * 0.6 + Math.sin(t * 41.3) * 0.4) * 0.018 * jitter;
    const jy = (Math.sin(t * 19.1) * 0.6 + Math.sin(t * 37.9) * 0.4) * 0.016 * jitter;

    camera.position.set(x + jx, y + jy, z);

    // Track the truck until the rip, then swing to look straight down the road
    // so passing through the bodywork does not whip the camera around.
    const truckZ = sampleCurve(TRUCK_Z_CURVE, p);
    target.set(0, 1.18 + p * 0.3, truckZ + 1.1);
    target.lerp(forward, through);
    camera.lookAt(target);

    if (jitter > 0) {
      camera.rotation.x += jy * 0.5;
      camera.rotation.y += jx * 0.5;
      camera.rotation.z += Math.sin(t * 27.3) * 0.006 * jitter;
    }

    if (Math.abs(fov - lastFov.current) > 0.01) {
      camera.fov = fov;
      camera.updateProjectionMatrix();
      lastFov.current = fov;
    }
  });

  return null;
}

