"use client";

import { useFrame } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import * as THREE from "three";
import type { LoaderCapabilities } from "@/lib/loader/capabilities";
import { TRUCK_Z_CURVE, type TruckSceneState } from "@/lib/loader/sceneState";
import { createFlareTexture, createGlowSprite, sampleCurve } from "@/lib/loader/truckArt";

/**
 * Atmosphere: dust motes, speed streaks and the headlight flare.
 *
 * Dust is a single `Points` cloud and the streaks are one instanced mesh, so
 * the whole effects layer is two draw calls regardless of tier — only the
 * particle *count* scales down on weaker devices.
 *
 * "Motion blur" here is deliberately faked with stretched additive geometry
 * plus a DOM streak layer rather than a postprocessing pass: a real motion-blur
 * pass would mean pulling in `postprocessing` and running extra full-screen
 * render targets for a 2.7-second intro.
 */

function Dust({ state, caps }: { state: TruckSceneState; caps: LoaderCapabilities }) {
  const points = useRef<THREE.Points>(null);
  const sprite = useMemo(() => createGlowSprite(64), []);

  const { geometry, velocities } = useMemo(() => {
    const count = caps.dustCount;
    const positions = new Float32Array(count * 3);
    const speeds = new Float32Array(count);

    for (let i = 0; i < count; i += 1) {
      positions[i * 3] = (Math.random() - 0.5) * 22;
      positions[i * 3 + 1] = Math.random() * 7;
      positions[i * 3 + 2] = -80 + Math.random() * 92;
      speeds[i] = 2.4 + Math.random() * 7.5;
    }

    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    return { geometry: geo, velocities: speeds };
  }, [caps.dustCount]);

  useEffect(
    () => () => {
      geometry.dispose();
      sprite.dispose();
    },
    [geometry, sprite],
  );

  useFrame((_, delta) => {
    if (!state.running || !points.current) return;

    const attribute = geometry.getAttribute("position") as THREE.BufferAttribute;
    const array = attribute.array as Float32Array;
    // Wash of air pushed ahead of the truck, so dust streams at the viewer.
    const wind = 1 + state.dust * 4.5;

    for (let i = 0; i < velocities.length; i += 1) {
      const index = i * 3 + 2;
      array[index] += velocities[i] * wind * delta;

      // Recycle behind the truck once a mote passes the lens.
      if (array[index] > 12) {
        array[index] = -80;
        array[i * 3] = (Math.random() - 0.5) * 22;
        array[i * 3 + 1] = Math.random() * 7;
      }
    }
    attribute.needsUpdate = true;

    const material = points.current.material as THREE.PointsMaterial;
    material.opacity = 0.05 + state.dust * 0.42;
    material.size = 0.1 + state.dust * 0.16;
  });

  return (
    <points ref={points} geometry={geometry} frustumCulled={false}>
      <pointsMaterial
        map={sprite}
        transparent
        depthWrite={false}
        blending={THREE.AdditiveBlending}
        sizeAttenuation
        size={0.1}
        opacity={0.05}
        color="#d8c9a8"
      />
    </points>
  );
}

function SpeedStreaks({
  state,
  caps,
}: {
  state: TruckSceneState;
  caps: LoaderCapabilities;
}) {
  const mesh = useRef<THREE.InstancedMesh>(null);
  const dummy = useMemo(() => new THREE.Object3D(), []);

  const seeds = useMemo(
    () =>
      Array.from({ length: caps.streakCount }, () => ({
        x: (Math.random() - 0.5) * 16,
        y: 0.4 + Math.random() * 6,
        z: -70 + Math.random() * 80,
        speed: 26 + Math.random() * 44,
        length: 2.5 + Math.random() * 6,
      })),
    [caps.streakCount],
  );

  useFrame((_, delta) => {
    if (!state.running || !mesh.current) return;

    seeds.forEach((seed, index) => {
      seed.z += seed.speed * delta * (0.25 + state.streak);
      if (seed.z > 14) {
        seed.z = -70;
        seed.x = (Math.random() - 0.5) * 16;
        seed.y = 0.4 + Math.random() * 6;
      }

      dummy.position.set(seed.x, seed.y, seed.z);
      dummy.scale.set(0.03, 0.03, seed.length * (0.4 + state.streak));
      dummy.updateMatrix();
      mesh.current!.setMatrixAt(index, dummy.matrix);
    });

    mesh.current.instanceMatrix.needsUpdate = true;
    const material = mesh.current.material as THREE.MeshBasicMaterial;
    material.opacity = state.streak * 0.3;
  });

  return (
    <instancedMesh
      ref={mesh}
      args={[undefined, undefined, caps.streakCount]}
      frustumCulled={false}
    >
      <boxGeometry args={[1, 1, 1]} />
      <meshBasicMaterial
        transparent
        opacity={0}
        depthWrite={false}
        blending={THREE.AdditiveBlending}
        color="#c9b68d"
      />
    </instancedMesh>
  );
}

function HeadlightFlare({ state }: { state: TruckSceneState }) {
  const group = useRef<THREE.Group>(null);
  const flare = useMemo(() => createFlareTexture(256), []);
  const materials = useRef<THREE.MeshBasicMaterial[]>([]);

  useEffect(() => () => flare.dispose(), [flare]);

  useFrame(({ camera }) => {
    if (!state.running || !group.current) return;

    const truckZ = sampleCurve(TRUCK_Z_CURVE, state.p);
    group.current.position.z = truckZ + 3.3;
    // Billboard the flares so they always face the lens.
    group.current.quaternion.copy(camera.quaternion);

    const scale = 1 + state.flare * 5.5 + state.glow * 0.5;
    group.current.scale.setScalar(scale);

    materials.current.forEach((material) => {
      material.opacity = Math.min(1, state.glow * 0.2 + state.flare * 0.85);
    });
  });

  return (
    <group ref={group} position={[0, 1.18, 0]}>
      {[-0.86, 0.86].map((x, index) => (
        <mesh key={x} position={[x, 0, 0]}>
          <planeGeometry args={[2.6, 2.6]} />
          <meshBasicMaterial
            ref={(material) => {
              if (material) materials.current[index] = material;
            }}
            map={flare}
            transparent
            opacity={0}
            depthWrite={false}
            depthTest={false}
            blending={THREE.AdditiveBlending}
            toneMapped={false}
          />
        </mesh>
      ))}
    </group>
  );
}

export function TruckEffects({
  state,
  caps,
}: {
  state: TruckSceneState;
  caps: LoaderCapabilities;
}) {
  return (
    <>
      <Dust state={state} caps={caps} />
      {caps.tier !== "low" && <SpeedStreaks state={state} caps={caps} />}
      <HeadlightFlare state={state} />
    </>
  );
}

"use client";

import { useFrame } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import * as THREE from "three";
import type { LoaderCapabilities } from "@/lib/loader/capabilities";
import { TRUCK_Z_CURVE, type TruckSceneState } from "@/lib/loader/sceneState";
import {
  createContactShadowTexture,
  createGlowSprite,
  createRoadTexture,
  sampleCurve,
  TRUCK_ART,
} from "@/lib/loader/truckArt";

/**
 * Road, fog and lighting.
 *
 * Deliberately minimal: one textured plane, one contact shadow, two additive
 * light pools standing in for wet-asphalt reflections, and three lights. All
 * textures are generated on a canvas, so the environment adds no download.
 */
export function TruckEnvironment({
  state,
  caps,
}: {
  state: TruckSceneState;
  caps: LoaderCapabilities;
}) {
  const road = useMemo(() => createRoadTexture(), []);
  const shadowBlob = useMemo(() => createContactShadowTexture(), []);
  const pool = useMemo(() => createGlowSprite(128), []);

  const shadowRef = useRef<THREE.Mesh>(null);
  const poolRef = useRef<THREE.Group>(null);
  const poolMaterials = useRef<THREE.MeshBasicMaterial[]>([]);
  const keyLight = useRef<THREE.DirectionalLight>(null);

  useEffect(
    () => () => {
      road.dispose();
      shadowBlob.dispose();
      pool.dispose();
    },
    [road, shadowBlob, pool],
  );

  useFrame(() => {
    if (!state.running) return;

    const truckZ = sampleCurve(TRUCK_Z_CURVE, state.p);

    // Road only scrolls while the camera itself is moving fast (the rip).
    road.offset.y = -state.through * 1.4;

    // Contact shadow tracks the truck and tightens as it gets closer.
    if (shadowRef.current) {
      shadowRef.current.position.z = truckZ - 0.3;
      const tight = 1 - state.p * 0.22;
      shadowRef.current.scale.set(4.6 * tight, 8.4 * tight, 1);
      const material = shadowRef.current.material as THREE.MeshBasicMaterial;
      material.opacity = 0.32 + state.p * 0.3;
    }

    // Headlight pools on the asphalt — cheap stand-in for a real reflector.
    if (poolRef.current) {
      poolRef.current.position.z = truckZ + 7;
      poolMaterials.current.forEach((material) => {
        material.opacity = Math.min(0.5, state.glow * 0.16);
      });
    }

    if (keyLight.current) {
      keyLight.current.intensity = 0.32 + state.glow * 0.1;
    }
  });

  return (
    <>
      {/* Deep atmospheric falloff: the truck emerges from this. */}
      <fogExp2 attach="fog" args={[TRUCK_ART.asphalt, 0.0165]} />
      <color attach="background" args={[TRUCK_ART.asphalt]} />

      <ambientLight intensity={0.22} color="#43506b" />

      {/* Cold moonlight rim so the bodywork reads against the dark. */}
      <directionalLight
        ref={keyLight}
        position={[-7, 9, -4]}
        intensity={0.34}
        color="#8fa5d6"
        castShadow={caps.shadows}
        shadow-mapSize-width={caps.shadowMapSize}
        shadow-mapSize-height={caps.shadowMapSize}
        shadow-camera-near={1}
        shadow-camera-far={60}
        shadow-camera-left={-12}
        shadow-camera-right={12}
        shadow-camera-top={12}
        shadow-camera-bottom={-12}
        shadow-bias={-0.0012}
      />

      {/* Warm bounce from the direction the truck is driving toward. */}
      <pointLight position={[0, 3, 26]} intensity={12} distance={40} color={TRUCK_ART.gold} />

      {/* Road */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, 0, -60]}
        receiveShadow={caps.shadows}
      >
        <planeGeometry args={[26, 320]} />
        <meshStandardMaterial
          map={road}
          roughness={0.58}
          metalness={0.35}
          color="#8a8a92"
        />
      </mesh>

      {/* Contact shadow under the truck */}
      <mesh ref={shadowRef} rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.012, 0]}>
        <planeGeometry args={[1, 1]} />
        <meshBasicMaterial
          map={shadowBlob}
          transparent
          opacity={0.32}
          depthWrite={false}
          color="#000000"
        />
      </mesh>

      {/* Headlight pools */}
      <group ref={poolRef}>
        {[-0.9, 0.9].map((x, index) => (
          <mesh key={x} rotation={[-Math.PI / 2, 0, 0]} position={[x, 0.02, 0]}>
            <planeGeometry args={[3.4, 18]} />
            <meshBasicMaterial
              ref={(material) => {
                if (material) poolMaterials.current[index] = material;
              }}
              map={pool}
              transparent
              opacity={0}
              depthWrite={false}
              blending={THREE.AdditiveBlending}
              color="#ffd9a0"
            />
          </mesh>
        ))}
      </group>
    </>
  );
}

