"use client";

import {
  Component,
  lazy,
  Suspense,
  useCallback,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { TruckFallback } from "@/components/loader/TruckFallback";
import { useMotion } from "@/components/providers/MotionProvider";
import { gsap, registerGsap } from "@/lib/gsap";
import { getCapabilities, type LoaderCapabilities } from "@/lib/loader/capabilities";
import { disposeHorn, playHorn, primeHorn } from "@/lib/loader/horn";
import { HARD_TIMEOUT, timeout, waitForCriticalResources } from "@/lib/loader/resources";
import { createSceneState } from "@/lib/loader/sceneState";
import {
  createLoaderReveal,
  createTruckExit,
  createTruckIntro,
  type IntroLayers,
} from "@/lib/loader/timelines";
import { TEXTURE_PATHS } from "@/lib/loader/truckArt";

registerGsap();

/** `three` and the scene graph are only fetched when 3D is actually viable. */
const TruckScene = lazy(() => import("@/components/loader/TruckScene"));

/** Any throw inside the WebGL tree degrades to the CSS truck. */
class SceneBoundary extends Component<
  { children: ReactNode; onError: () => void },
  { failed: boolean }
> {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidCatch(error: unknown) {
    console.warn("[loader] 3D scene failed, using CSS fallback", error);
    this.props.onError();
  }

  render() {
    return this.state.failed ? null : this.props.children;
  }
}

/**
 * The truck intro.
 *
 * Runs a single GSAP master clock (intro → exit → reveal) while the rest of the
 * site boots in parallel. The website is revealed as soon as the cinematic
 * finishes *and* critical resources are ready, with a hard 3s ceiling so a slow
 * network can never hold the visitor hostage.
 */
export function TruckLoader() {
  const { reduced, setReady } = useMotion();

  // `visible` starts true on both server and client so the first paint is
  // identical and hydration cannot mismatch. Everything capability-dependent
  // is resolved in an effect below.
  const [visible, setVisible] = useState(true);
  const [caps, setCaps] = useState<LoaderCapabilities | null>(null);
  const [use3D, setUse3D] = useState(false);
  const [sceneMounted, setSceneMounted] = useState(false);

  const rootRef = useRef<HTMLDivElement>(null);
  const vignetteRef = useRef<HTMLDivElement>(null);
  const streaksRef = useRef<HTMLDivElement>(null);
  const flashRef = useRef<HTMLDivElement>(null);
  const curtainRef = useRef<HTMLDivElement>(null);
  const wordmarkRef = useRef<HTMLDivElement>(null);
  const badgeRef = useRef<HTMLDivElement>(null);
  const captionRef = useRef<HTMLParagraphElement>(null);

  const state = useRef(createSceneState());
  const startedRef = useRef(false);

  const handleSceneFailure = useCallback(() => {
    setUse3D(false);
    setSceneMounted(false);
  }, []);

  // --- Decide the render path once, on the client.
  useEffect(() => {
    const capabilities = getCapabilities();
    setCaps(capabilities);

    const enable3D = capabilities.webgl && !reduced;
    setUse3D(enable3D);
    setSceneMounted(enable3D);

    if (!reduced) primeHorn();
  }, [reduced]);

  // --- Run the cinematic.
  useEffect(() => {
    if (!caps || startedRef.current) return;
    startedRef.current = true;

    const layers: IntroLayers = {
      vignette: vignetteRef.current,
      streaks: streaksRef.current,
      flash: flashRef.current,
      curtain: curtainRef.current,
      wordmark: wordmarkRef.current,
      badge: badgeRef.current,
      caption: captionRef.current,
    };

    let cancelled = false;

    // Reduced motion: no camera work, no shake, no horn — just a short,
    // legible hand-off so navigation and content stay fully functional.
    const cover = gsap.timeline({ paused: true });

    if (reduced) {
      if (layers.curtain) {
        cover.set(layers.curtain, { opacity: 1, clipPath: "inset(0% 0% 0% 0%)" });
      }
      cover.to({}, { duration: 0.35 });
    } else {
      cover.add(createTruckIntro({ state: state.current, layers, onHorn: playHorn }));
      cover.add(createTruckExit({ state: state.current, layers }));
    }

    const finish = async () => {
      const coverDone = cover.play().then(() => undefined);

      // The cinematic and the site load race each other; whichever finishes
      // last decides the reveal, but never later than HARD_TIMEOUT.
      const outcome = await Promise.race([
        Promise.all([
          coverDone,
          waitForCriticalResources([TEXTURE_PATHS.panel, TEXTURE_PATHS.side]),
        ]).then(() => "ready" as const),
        timeout(HARD_TIMEOUT),
      ]);

      if (cancelled) return;

      // Timed out mid-cinematic: snap the cover timeline to its end so the
      // curtain is definitely covering the viewport before we tear down WebGL.
      if (outcome === "timeout" && cover.progress() < 1) {
        cover.progress(1, false);
      }

      // Safe to release the GPU now — the curtain hides the swap completely.
      state.current.running = false;
      setSceneMounted(false);

      await createLoaderReveal({
        layers,
        onReveal: setReady,
        reduced,
      });

      if (cancelled) return;
      setVisible(false);
      disposeHorn();
    };

    void finish();

    return () => {
      cancelled = true;
      cover.kill();
    };
  }, [caps, reduced, setReady]);

  // Failsafe independent of GSAP: if anything above stalls (a thrown error, a
  // suspended ticker in a backgrounded tab), the site still becomes usable.
  useEffect(() => {
    const timer = window.setTimeout(() => {
      setReady();
      setVisible(false);
    }, HARD_TIMEOUT + 1200);

    return () => window.clearTimeout(timer);
  }, [setReady]);

  if (!visible) return null;

  return (
    <>
      {/* Without JS the cinematic can never finish, so never show it. */}
      <noscript>
        <style dangerouslySetInnerHTML={{ __html: "#truck-loader{display:none!important}" }} />
      </noscript>

      <div
        id="truck-loader"
        ref={rootRef}
        className="fixed inset-0 z-[110] overflow-hidden bg-background"
        aria-hidden
      >
        {/* --- 3D layer, or the CSS truck when 3D is not viable. */}
        <div className="absolute inset-0">
          {use3D && sceneMounted && caps ? (
            <SceneBoundary onError={handleSceneFailure}>
              <Suspense fallback={<TruckFallback reduced={reduced} />}>
                <TruckScene
                  state={state.current}
                  caps={caps}
                  reduced={reduced}
                  onContextLost={handleSceneFailure}
                />
              </Suspense>
            </SceneBoundary>
          ) : (
            <TruckFallback reduced={reduced} />
          )}
        </div>

        {/* --- Atmospheric DOM layers, driven by the same GSAP clock. */}
        <div
          ref={vignetteRef}
          className="pointer-events-none absolute inset-0"
          style={{
            background:
              "radial-gradient(ellipse at 50% 58%, transparent 28%, rgba(7,7,10,0.72) 78%, #07070a 100%)",
          }}
        />

        <div
          ref={streaksRef}
          className="pointer-events-none absolute inset-0 truck-speed-streaks opacity-0"
        />

        <div
          ref={flashRef}
          className="pointer-events-none absolute inset-0 opacity-0"
          style={{
            background:
              "radial-gradient(circle at 50% 52%, #fff6e2 0%, rgba(255,224,168,0.72) 34%, rgba(255,200,120,0) 72%)",
          }}
        />

        {/* --- Wordmark + truck-art caption. */}
        <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-end pb-[12vh]">
          <div
            ref={wordmarkRef}
            className="font-serif text-[clamp(3rem,12vw,8rem)] leading-none text-foreground opacity-0"
            style={{ letterSpacing: "0.22em" }}
          >
            RMW
          </div>
          <p
            ref={captionRef}
            className="mt-4 font-mono text-[10px] uppercase tracking-[0.42em] text-muted opacity-0 md:text-[11px]"
          >
            Truck art in motion
          </p>
        </div>

        {/* --- Horn badge, punched in on the horn beat. */}
        <div
          ref={badgeRef}
          className="pointer-events-none absolute left-1/2 top-[16vh] w-[min(58vw,420px)] -translate-x-1/2 opacity-0"
        >
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={TEXTURE_PATHS.hornBadge}
            alt=""
            width={640}
            height={249}
            aria-hidden
            className="h-auto w-full"
          />
        </div>

        {/* --- Truck-art curtain. Covers the viewport so WebGL can be disposed
                behind it, then lifts away to reveal the website. */}
        <div
          ref={curtainRef}
          className="absolute inset-0 truck-art-panel opacity-0"
          style={{ clipPath: "inset(100% 0% 0% 0%)" }}
        />
      </div>
    </>
  );
}

