import type { RefObject } from "react";
import { TEXTURE_PATHS } from "@/lib/loader/truckArt";

export type TruckTransitionRefs = {
  root: RefObject<HTMLDivElement | null>;
  panel: RefObject<HTMLDivElement | null>;
  pattern: RefObject<HTMLDivElement | null>;
  truck: RefObject<HTMLDivElement | null>;
  label: RefObject<HTMLSpanElement | null>;
  streaks: RefObject<HTMLDivElement | null>;
};

/**
 * The persistent navigation overlay.
 *
 * Lives above the Barba container for the whole session and is never unmounted,
 * so a transition is only ever `clip-path` + `transform` + `opacity` on already
 * composited layers — no WebGL context, no new DOM, no layout work. This is why
 * the intro can dispose its renderer while navigation still feels like the truck.
 */
export function TruckTransition({ refs }: { refs: TruckTransitionRefs }) {
  return (
    <div
      ref={refs.root}
      className="pointer-events-none fixed inset-0 z-[100]"
      aria-hidden
    >
      <div
        ref={refs.panel}
        className="absolute inset-0 overflow-hidden bg-background opacity-0"
        style={{ clipPath: "inset(100% 0% 0% 0%)" }}
      >
        {/* Authentic truck-art bands, tiled. Shares the texture the 3D cargo
            box uses, so it is already in cache after the intro. */}
        <div ref={refs.pattern} className="absolute inset-[-8%] truck-art-panel" />

        {/* Darkening wash keeps the label legible over the pattern. */}
        <div className="absolute inset-0 bg-background/62" />

        <div
          ref={refs.streaks}
          className="absolute inset-0 truck-speed-streaks opacity-0"
        />

        {/* The truck drives across the seam. */}
        <div
          ref={refs.truck}
          className="absolute top-1/2 left-1/2 w-[min(88vw,980px)] -translate-y-1/2 opacity-0"
