"use client";

import { useLenis } from "lenis/react";
import { usePathname, useRouter } from "next/navigation";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  TruckTransition,
  type TruckTransitionRefs,
} from "@/components/loader/TruckTransition";
import { useMotion } from "@/components/providers/MotionProvider";
import { createBarbaConfig } from "@/lib/barba/barbaConfig";
import { barba, CONTAINER_SELECTOR } from "@/lib/barba/core";
import { namespaceFor } from "@/lib/barba/namespaces";
import type { BarbaRouterBridge } from "@/lib/barba/types";
import { registerGsap, ScrollTrigger } from "@/lib/gsap";
import type { TransitionLayers } from "@/lib/loader/timelines";

registerGsap();

type BarbaNavigationValue = {
  /** Runs the Barba lifecycle for an internal href. */
  navigate: (href: string, trigger?: HTMLElement) => void;
  isTransitioning: boolean;
};

const BarbaNavigationContext = createContext<BarbaNavigationValue | null>(null);

/**
 * Wires the Barba lifecycle engine to the Next.js App Router.
 *
 * Barba owns *when* a transition happens and which rule applies; GSAP owns how
 * it looks; Next owns the actual navigation and rendering. The provider is the
 * only place those three meet.
 */
export function BarbaProvider({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const pathname = usePathname();
  const lenis = useLenis();
  const { reduced } = useMotion();

  const [isTransitioning, setIsTransitioning] = useState(false);

  const refs: TruckTransitionRefs = {
    root: useRef<HTMLDivElement>(null),
    panel: useRef<HTMLDivElement>(null),
    pattern: useRef<HTMLDivElement>(null),
    truck: useRef<HTMLDivElement>(null),
    label: useRef<HTMLSpanElement>(null),
    streaks: useRef<HTMLDivElement>(null),
  };

  // Kept in a ref so the Barba bridge (created once) always sees live values.
  const reducedRef = useRef(reduced);
  reducedRef.current = reduced;

  const lenisRef = useRef(lenis);
  lenisRef.current = lenis;

  const pendingRef = useRef<{
    path: string;
    resolve: (container: HTMLElement | null) => void;
  } | null>(null);
  const isFirstRoute = useRef(true);

  const getLayers = useCallback(
    (): TransitionLayers => ({
      root: refs.root.current,
      panel: refs.panel.current,
      pattern: refs.pattern.current,
      truck: refs.truck.current,
      label: refs.label.current,
      streaks: refs.streaks.current,
    }),
    // Refs are stable for the provider's lifetime.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  const scrollToTop = useCallback(() => {
    const instance = lenisRef.current;
    if (instance) instance.scrollTo(0, { immediate: true, force: true });
    else window.scrollTo(0, 0);
  }, []);

  const refreshScroll = useCallback(() => {
    requestAnimationFrame(() => ScrollTrigger.refresh());
  }, []);

  // --- Initialise the engine once.
  useEffect(() => {
    const bridge: BarbaRouterBridge = {
      push: (path) => router.push(path),
      waitForContainer: (path) =>
        new Promise((resolve) => {
          pendingRef.current = { path, resolve };
        }),
      getContainer: () => document.querySelector<HTMLElement>(CONTAINER_SELECTOR),
      getNamespace: (path) => namespaceFor(path),
      getCurrentPath: () => window.location.pathname,
    };

    barba.use(bridge);
    barba.init(
      createBarbaConfig({
        getLayers,
        isReduced: () => reducedRef.current,
        scrollToTop,
        refreshScroll,
      }),
    );

    return () => {
      barba.destroy();
    };
  }, [router, getLayers, scrollToTop, refreshScroll]);

  // --- Resolve the incoming container, or handle back/forward.
  useEffect(() => {
    if (isFirstRoute.current) {
      isFirstRoute.current = false;
      barba.setInitialPage(namespaceFor(pathname), pathname);
      return;
    }

    const container = document.querySelector<HTMLElement>(CONTAINER_SELECTOR);
    const pending = pendingRef.current;

    if (pending) {
      pendingRef.current = null;
      pending.resolve(container);
      return;
    }

    // Reached without `barba.go()` — browser back/forward, or a plain
    // `router.push` elsewhere in the app. Next has already swapped the DOM, so
    // only the enter half of the lifecycle can run.
    scrollToTop();
    void barba.settleFromHistory(pathname, container);
  }, [pathname, scrollToTop]);

  const navigate = useCallback((href: string, trigger?: HTMLElement) => {
    if (barba.isRunning) return;

    setIsTransitioning(true);
    void barba.go(href, trigger ?? "barba").finally(() => setIsTransitioning(false));
  }, []);

  const value = useMemo(
    () => ({ navigate, isTransitioning }),
    [navigate, isTransitioning],
  );

  return (
    <BarbaNavigationContext.Provider value={value}>
      {children}
      <TruckTransition refs={refs} />
    </BarbaNavigationContext.Provider>
  );
}

export function useBarbaNavigation() {
  const context = useContext(BarbaNavigationContext);
  if (!context) {
    throw new Error("useBarbaNavigation must be used within BarbaProvider");
  }
  return context;
}
